import * as readline from 'readline'

// Constants for default ports
const DEFAULT_PORTS = {
  'http': 80,
  'ws': 80,
  'https': 443,
  'wss': 443,
  'ftp': 21
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/

