 * Parse authority into userinfo, host, and port
 */
function parseAuthority(authority) {
  if (!authority) return { userinfo: undefined, host: undefined, port: undefined }

  // Extract userinfo (everything before last @)
  let userinfo = undefined
  let hostport = authority
  const lastAtIdx = authority.lastIndexOf('@')
  if (lastAtIdx !== -1) {
    userinfo = authority.substring(0, lastAtIdx)
    hostport = authority.substring(lastAtIdx + 1)
  }

  // Extract port
  let host = hostport
  let port = undefined

  // Check for IPv6
  if (hostport.startsWith('[')) {
    const closeBracketIdx = hostport.indexOf(']')
    if (closeBracketIdx !== -1) {
      host = hostport.substring(0, closeBracketIdx + 1)
      const afterBracket = hostport.substring(closeBracketIdx + 1)
      if (afterBracket.startsWith(':')) {
        port = afterBracket.substring(1)
      }
    }
