    else if (input.startsWith('/.//', i)) {
      // Replace with /
      i += 3
    } else if (input.startsWith('/./', i) && i + 3 === input.length) {
      // Special case: "/./" at end becomes "/"
      i += 2
    }
    // C: If the input buffer begins with a prefix of "/../"
    else if (input.startsWith('/../', i)) {
      if (output.length > 0) output.pop()
      i += 4
    } else if (input.startsWith('/../', i) && i + 3 === input.length) {
      // Special case: "/.." at end
      if (output.length > 0) output.pop()
      i += 3
    }
