      if (normalized.error) {
        process.stderr.write(`error: line ${lineNum}: the ${normalized.component} has a truncated percent-encoding\n`)
        process.exit(2)
      }

      process.stdout.write(normalized.uri + '\n')
    }
  }

  process.exit(0)
}

