import * as readline from 'readline'

// Constants for default ports
const DEFAULT_PORTS = {
  'http': 80,
  'ws': 80,
  'https': 443,
  'wss': 443,
  'ftp': 21
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Parse a URI reference into its components.
 * Returns { scheme, authority, path, query, fragment }
 */
function parseURI(uri) {
  let scheme = undefined
  let authority = undefined
  let path = ''
  let query = undefined
  let fragment = undefined

  let remaining = uri

  // Extract fragment
  const fragmentIdx = remaining.indexOf('#')
  if (fragmentIdx !== -1) {
    fragment = remaining.substring(fragmentIdx + 1)
    remaining = remaining.substring(0, fragmentIdx)
  }

  // Extract query
  const queryIdx = remaining.indexOf('?')
  if (queryIdx !== -1) {
    query = remaining.substring(queryIdx + 1)
    remaining = remaining.substring(0, queryIdx)
  }

  // Extract scheme (must be before any /, ?, #)
  let schemeIdx = remaining.indexOf(':')
  if (schemeIdx !== -1) {
    // Check if : is before any /, ?, # (which should already be removed)
    const hasSlashBefore = remaining.substring(0, schemeIdx).indexOf('/') !== -1
    const hasQBefore = remaining.substring(0, schemeIdx).indexOf('?') !== -1
    const hasHashBefore = remaining.substring(0, schemeIdx).indexOf('#') !== -1

    if (!hasSlashBefore && !hasQBefore && !hasHashBefore) {
      scheme = remaining.substring(0, schemeIdx)
      remaining = remaining.substring(schemeIdx + 1)
    }
  }

  // Extract authority (starts with //)
  if (remaining.startsWith('//')) {
    let endIdx = remaining.length
    const slashIdx = remaining.indexOf('/', 2)
    const qIdx = remaining.indexOf('?', 2)
    const hashIdx = remaining.indexOf('#', 2)

    if (slashIdx !== -1) endIdx = Math.min(endIdx, slashIdx)
    if (qIdx !== -1) endIdx = Math.min(endIdx, qIdx)
    if (hashIdx !== -1) endIdx = Math.min(endIdx, hashIdx)

    authority = remaining.substring(2, endIdx)
    remaining = remaining.substring(endIdx)
  }

  // The rest is path
  path = remaining

  return { scheme, authority, path, query, fragment }
}

/**
 * Parse authority into userinfo, host, and port
 */
function parseAuthority(authority) {
  if (!authority) return { userinfo: undefined, host: undefined, port: undefined }

  // Extract userinfo (everything before last @)
  let userinfo = undefined
  let hostport = authority
  const lastAtIdx = authority.lastIndexOf('@')
  if (lastAtIdx !== -1) {
    userinfo = authority.substring(0, lastAtIdx)
    hostport = authority.substring(lastAtIdx + 1)
  }

  // Extract port
  let host = hostport
  let port = undefined

  // Check for IPv6
  if (hostport.startsWith('[')) {
    const closeBracketIdx = hostport.indexOf(']')
    if (closeBracketIdx !== -1) {
      host = hostport.substring(0, closeBracketIdx + 1)
      const afterBracket = hostport.substring(closeBracketIdx + 1)
      if (afterBracket.startsWith(':')) {
        port = afterBracket.substring(1)
      }
    }
  } else {
    // For non-IPv6, port is after first :
    const colonIdx = hostport.indexOf(':')
    if (colonIdx !== -1) {
      host = hostport.substring(0, colonIdx)
      port = hostport.substring(colonIdx + 1)
    }
  }

  return { userinfo, host, port }
}

/**
 * Check if a string has truncated percent-encoding
 * Returns { valid, component } where component is the one with the error or null
 */
function checkPercentEncoding(uri) {
  const components = ['userinfo', 'host', 'path', 'query', 'fragment']
  const { scheme, authority, path, query, fragment } = parseURI(uri)

  if (authority) {
    const { userinfo, host, port } = parseAuthority(authority)
    if (userinfo && !isValidPercentEncoding(userinfo)) return { valid: false, component: 'userinfo' }
    if (host && !isValidPercentEncoding(host)) return { valid: false, component: 'host' }
  }
  if (!isValidPercentEncoding(path)) return { valid: false, component: 'path' }
  if (query !== undefined && !isValidPercentEncoding(query)) return { valid: false, component: 'query' }
  if (fragment !== undefined && !isValidPercentEncoding(fragment)) return { valid: false, component: 'fragment' }

  return { valid: true, component: null }
}

function isValidPercentEncoding(str) {
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      if (i + 2 >= str.length) return false
      const hex1 = str[i + 1]
      const hex2 = str[i + 2]
      if (!/[0-9A-Fa-f]/.test(hex1) || !/[0-9A-Fa-f]/.test(hex2)) return false
      i += 2
    }
  }
  return true
}

/**
 * Normalize percent-encodings in a component
 */
function normalizePercentEncoding(str) {
  if (!str) return str
  return str.replace(/%([0-9A-Fa-f]{2})/g, (match, hex) => {
    const upperHex = hex.toUpperCase()
    const char = String.fromCharCode(parseInt(upperHex, 16))
    if (UNRESERVED.test(char)) {
      return char
    }
    return '%' + upperHex
